#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeNode: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = Node

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> Node {
        return Node(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: Node) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Node {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: Node, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}




#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNode_lift(_ pointer: UnsafeMutableRawPointer) throws -> Node {
    return try FfiConverterTypeNode.lift(pointer)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeNode_lower(_ value: Node) -> UnsafeMutableRawPointer {
    return FfiConverterTypeNode.lower(value)
}


public struct AnnounceRecord {
    public var destinationHex: String
    public var identityHex: String
    public var destinationKind: String
    public var announceClass: AnnounceClass
    public var appData: String
    public var displayName: String?
    public var hops: UInt8
    public var interfaceHex: String
    public var receivedAtMs: UInt64

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(destinationHex: String, identityHex: String, destinationKind: String, announceClass: AnnounceClass, appData: String, displayName: String?, hops: UInt8, interfaceHex: String, receivedAtMs: UInt64) {
        self.destinationHex = destinationHex
        self.identityHex = identityHex
        self.destinationKind = destinationKind
        self.announceClass = announceClass
        self.appData = appData
        self.displayName = displayName
        self.hops = hops
        self.interfaceHex = interfaceHex
        self.receivedAtMs = receivedAtMs
    }
}



extension AnnounceRecord: Equatable, Hashable {
    public static func ==(lhs: AnnounceRecord, rhs: AnnounceRecord) -> Bool {
        if lhs.destinationHex != rhs.destinationHex {
            return false
        }
        if lhs.identityHex != rhs.identityHex {
            return false
        }
        if lhs.destinationKind != rhs.destinationKind {
